struct P {
    P(int x, int y) { std::cout << "ctor\n"; }
    P(const P&)     { std::cout << "copy\n"; }
    P(P&&) noexcept { std::cout << "move\n"; }
};

std::vector<P> v;
v.reserve(2);            // no reallocation noise
v.push_back(P(1, 2));    // ctor, move
v.emplace_back(1, 2);    // ctor

std::vector<std::string> v;
std::string s = "hi";
v.push_back(s);              // copy
v.emplace_back(s);           // also a copy: same thing
v.push_back("hi");           // temporary string, then move
v.emplace_back("hi");        // constructed in place

std::vector<std::unique_ptr<int>> w;
w.push_back(new int(1));     // error: explicit constructor
w.emplace_back(new int(1));  // compiles, but can leak
